import { Types } from "./types";

const initialState = {
    count: 1,
};

export const counterReducer = (state = initialState, action) => {
    switch (action.type) {
        case Types.increaseCount:
            return {

            };
        case Types.decreaseCount:
            return state - 1;
        default:
            return state;
    }
}
